import assert from 'node:assert/strict';
const dir = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '18080', DB_PATH: join(dir, 'db.sqlite') }, detached: true, stdio: ['ignore', 'pipe', 'pipe'] });
